@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client
@using ShipmentTracker.Client.Layout
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services

@page "/"

<PageTitle>Track Your Shipment</PageTitle>

<div class="container mt-4">
    <h1>Track Your Shipment</h1>
    <p class="text-muted">Enter your tracking number to check the status and estimated delivery of your shipment.</p>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="e.g. TRK-10001"
                       @bind="trackingNumber" @bind:event="oninput"
                       @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                    @if (isLoading)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    }
                    Track
                </button>
            </div>
        </div>
    </div>

    @if (errorMessage is not null)
    {
        <div class="alert alert-warning" role="alert">@errorMessage</div>
    }

    @if (shipment is not null)
    {
        <div class="card">
            <div class="card-header d-flex justify-content-between align-items-center">
                <h5 class="mb-0">@shipment.TrackingNumber</h5>
                <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <dl>
                            <dt>Recipient</dt>
                            <dd>@shipment.RecipientName</dd>
                            <dt>Description</dt>
                            <dd>@shipment.Description</dd>
                            <dt>Origin</dt>
                            <dd>@shipment.Origin</dd>
                            <dt>Destination</dt>
                            <dd>@shipment.Destination</dd>
                        </dl>
                    </div>
                    <div class="col-md-6">
                        <dl>
                            <dt>Shipped Date</dt>
                            <dd>@shipment.ShippedDate.ToString("MMM dd, yyyy")</dd>
                            <dt>Estimated Delivery</dt>
                            <dd>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</dd>
                            @if (shipment.ActualDelivery.HasValue)
                            {
                                <dt>Actual Delivery</dt>
                                <dd>@shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</dd>
                            }
                        </dl>
                    </div>
                </div>

                <div class="mt-3">
                    <h6>Shipment Progress</h6>
                    <div class="progress" style="height: 24px;">
                        <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                             role="progressbar"
                             style="width: @(GetProgressPercent(shipment.Status))%">
                            @shipment.Status
                        </div>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

